import React, { useState } from 'react';
import { Mail, Github, Smartphone, MapPin, ChevronDown, Calendar } from 'lucide-react';
import { PERSONAL_INFO } from '../constants';

const Sidebar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);

  const toggleSidebar = () => setIsOpen(!isOpen);

  return (
    <aside className="bg-[#1e1e1f] border border-[#383838] rounded-3xl p-6 lg:p-8 shadow-lg w-full h-fit lg:sticky lg:top-10 transition-all z-10 mb-6 lg:mb-0">
      <div className="flex flex-col items-center gap-4 lg:gap-6">
        <div className="bg-[#383838] rounded-3xl p-1 relative">
          <img 
            src={PERSONAL_INFO.avatar} 
            alt={PERSONAL_INFO.name} 
            className="w-32 h-32 lg:w-40 lg:h-40 rounded-3xl object-cover"
          />
        </div>

        <div className="text-center">
          <h1 className="text-2xl font-bold text-white mb-2 whitespace-nowrap">{PERSONAL_INFO.name}</h1>
          <span className="bg-[#2b2b2c] text-white text-xs px-3 py-1 rounded-lg font-light">
            {PERSONAL_INFO.role}
          </span>
        </div>

        {/* Mobile Toggle Button */}
        <button 
          onClick={toggleSidebar}
          className="lg:hidden absolute top-0 right-0 p-4 text-[#ffdb70] hover:bg-[#2b2b2c] rounded-tr-3xl rounded-bl-3xl transition-colors"
        >
          <ChevronDown className={`w-6 h-6 transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`} />
        </button>
      </div>

      <div className={`sidebar-info-more ${isOpen ? 'active' : ''} lg:opacity-100 lg:visible lg:max-h-full overflow-hidden mt-6 border-t border-[#383838] lg:border-none pt-6 lg:pt-0`}>
        <ul className="grid gap-6">
          <ContactItem 
            icon={<Mail className="w-5 h-5 text-[#ffdb70]" />} 
            title="Email" 
            value={PERSONAL_INFO.email} 
            link={`mailto:${PERSONAL_INFO.email}`}
          />
          <ContactItem 
            icon={<Github className="w-5 h-5 text-[#ffdb70]" />} 
            title="GitHub" 
            value="thivgo"
            link={`https://${PERSONAL_INFO.github}`}
          />
          <ContactItem 
            icon={<MapPin className="w-5 h-5 text-[#ffdb70]" />} 
            title="Localização" 
            value={PERSONAL_INFO.location} 
          />
          <ContactItem 
            icon={<Calendar className="w-5 h-5 text-[#ffdb70]" />} 
            title="Semestre" 
            value="3º Período" 
          />
        </ul>

        <div className="flex justify-center gap-4 mt-8">
           {/* Social Icons could go here */}
        </div>
      </div>
    </aside>
  );
};

interface ContactItemProps {
  icon: React.ReactNode;
  title: string;
  value: string;
  link?: string;
}

const ContactItem: React.FC<ContactItemProps> = ({ icon, title, value, link }) => (
  <li className="flex items-center gap-4 w-full">
    <div className="bg-[#202022] p-3 rounded-xl shadow-sm border border-[#383838] flex-shrink-0">
      {icon}
    </div>
    <div className="flex flex-col truncate">
      <span className="text-xs text-gray-400 uppercase tracking-wide">{title}</span>
      {link ? (
        <a href={link} target="_blank" rel="noreferrer" className="text-sm text-gray-200 hover:text-[#ffdb70] transition-colors truncate block w-full">
          {value}
        </a>
      ) : (
        <span className="text-sm text-gray-200 truncate block w-full">{value}</span>
      )}
    </div>
  </li>
);

export default Sidebar;

import React from 'react';
import { Page } from '../types';

interface NavbarProps {
  currentPage: Page;
  setPage: (page: Page) => void;
}

const Navbar: React.FC<NavbarProps> = ({ currentPage, setPage }) => {
  const navItems = [Page.ABOUT, Page.RESUME, Page.PORTFOLIO, Page.CONTACT];

  return (
    <nav className="absolute top-0 right-0 bg-[#2b2b2c] border border-[#383838] rounded-bl-3xl rounded-tr-3xl px-6 py-4 z-20 hidden lg:block">
      <ul className="flex gap-8">
        {navItems.map((item) => (
          <li key={item}>
            <button
              onClick={() => setPage(item)}
              className={`text-sm font-medium transition-colors hover:text-gray-300 ${
                currentPage === item ? 'text-[#ffdb70]' : 'text-gray-400'
              }`}
            >
              {item}
            </button>
          </li>
        ))}
      </ul>
    </nav>
  );
};

export const MobileNavbar: React.FC<NavbarProps> = ({ currentPage, setPage }) => {
  const navItems = [Page.ABOUT, Page.RESUME, Page.PORTFOLIO, Page.CONTACT];

  return (
    <nav className="fixed bottom-0 left-0 w-full bg-[#2b2b2c]/90 backdrop-blur-md border-t border-[#383838] z-50 lg:hidden rounded-t-2xl">
      <ul className="flex justify-around items-center py-4">
        {navItems.map((item) => (
          <li key={item}>
            <button
              onClick={() => setPage(item)}
              className={`text-xs font-medium transition-colors hover:text-gray-300 ${
                currentPage === item ? 'text-[#ffdb70]' : 'text-gray-400'
              }`}
            >
              {item}
            </button>
          </li>
        ))}
      </ul>
    </nav>
  );
};

export default Navbar;

import React from 'react';
import { PERSONAL_INFO, SERVICES } from '../constants';
import { Code, Palette, Smartphone, Globe } from 'lucide-react';

const About: React.FC = () => {
  const getIcon = (iconName: string) => {
    switch (iconName) {
      case 'code': return <Code className="w-8 h-8 text-[#ffdb70]" />;
      case 'palette': return <Palette className="w-8 h-8 text-[#ffdb70]" />;
      case 'smartphone': return <Smartphone className="w-8 h-8 text-[#ffdb70]" />;
      default: return <Globe className="w-8 h-8 text-[#ffdb70]" />;
    }
  };

  return (
    <article className="animate-fade-in">
      <header className="mb-8">
        <h2 className="text-3xl font-bold text-white relative inline-block pb-4 after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-10 after:h-1.5 after:bg-[#ffdb70] after:rounded-md">
          Sobre Mim
        </h2>
      </header>

      <section className="text-gray-300 leading-relaxed mb-10">
        <p className="bg-[#202022] p-6 rounded-2xl border border-[#383838] shadow-sm">
          {PERSONAL_INFO.bio}
        </p>
      </section>

      <section>
        <h3 className="text-xl font-bold text-white mb-6">O que eu faço</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {SERVICES.map((service, index) => (
            <div 
              key={index} 
              className="bg-[#202022] p-6 rounded-2xl border border-[#383838] shadow-sm flex items-start gap-4 hover:bg-[#2b2b2c] transition-colors"
            >
              <div className="flex-shrink-0 mt-1">
                {getIcon(service.icon)}
              </div>
              <div>
                <h4 className="text-white font-semibold mb-2 text-lg">{service.title}</h4>
                <p className="text-gray-400 text-sm leading-6">
                  {service.description}
                </p>
              </div>
            </div>
          ))}
        </div>
      </section>
    </article>
  );
};

export default About;

import React, { useState } from 'react';
import { Eye } from 'lucide-react';
import { PROJECTS } from '../constants';
import { Project } from '../types';

const Portfolio: React.FC = () => {
  const [filter, setFilter] = useState<string>('All');

  const categories = ['All', ...Array.from(new Set(PROJECTS.map((p) => p.category)))];

  const filteredProjects = filter === 'All' 
    ? PROJECTS 
    : PROJECTS.filter(project => project.category === filter);

  return (
    <article className="animate-fade-in">
      <header className="mb-8">
        <h2 className="text-3xl font-bold text-white relative inline-block pb-4 after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-10 after:h-1.5 after:bg-[#ffdb70] after:rounded-md">
          Portfólio
        </h2>
      </header>

      {/* Filter Buttons */}
      <div className="flex flex-wrap gap-4 mb-8">
        {categories.map((cat) => (
          <button
            key={cat}
            onClick={() => setFilter(cat)}
            className={`text-sm font-medium transition-colors hover:text-[#ffdb70] ${
              filter === cat ? 'text-[#ffdb70]' : 'text-gray-400'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Projects Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredProjects.map((project: Project) => (
          <div key={project.id} className="group relative">
            <div className="relative overflow-hidden rounded-2xl cursor-pointer">
              <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity z-10 flex items-center justify-center">
                <div className="bg-[#2b2b2c] p-3 rounded-xl">
                   <Eye className="w-6 h-6 text-[#ffdb70]" />
                </div>
              </div>
              <img 
                src={project.image} 
                alt={project.title} 
                className="w-full h-48 object-cover transform group-hover:scale-110 transition-transform duration-500"
              />
            </div>
            <div className="mt-4">
              <h3 className="text-white font-semibold text-lg group-hover:text-[#ffdb70] transition-colors">
                {project.title}
              </h3>
              <p className="text-gray-400 text-sm mt-1">{project.category}</p>
              <div className="flex gap-2 mt-2 flex-wrap">
                  {project.tech.map((t, i) => (
                      <span key={i} className="text-[10px] bg-[#202022] text-gray-300 px-2 py-1 rounded border border-[#383838]">
                          {t}
                      </span>
                  ))}
              </div>
            </div>
          </div>
        ))}
      </div>
    </article>
  );
};

export default Portfolio;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Navbar, { MobileNavbar } from './components/Navbar';
import About from './components/About';
import Resume from './components/Resume';
import Portfolio from './components/Portfolio';
import Contact from './components/Contact';
import { Page } from './types';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.ABOUT);

  const renderContent = () => {
    switch (currentPage) {
      case Page.ABOUT: return <About />;
      case Page.RESUME: return <Resume />;
      case Page.PORTFOLIO: return <Portfolio />;
      case Page.CONTACT: return <Contact />;
      default: return <About />;
    }
  };

  return (
    <main className="min-h-screen p-4 lg:p-14 flex justify-center bg-[#121212]">
      <div className="w-full max-w-[1250px] grid grid-cols-1 lg:grid-cols-4 gap-6 relative">

        {/* Left Sidebar (Personal Info) */}
        <div className="lg:col-span-1">
          <Sidebar />
        </div>

        {/* Main Content Area */}
        <div className="lg:col-span-3 w-full bg-[#1e1e1f] border border-[#383838] rounded-3xl relative min-h-[500px] mb-20 lg:mb-0">

          {/* Desktop Navigation */}
          <Navbar currentPage={currentPage} setPage={setCurrentPage} />

          {/* Content Container */}
          <div className="p-6 lg:p-10 pt-8 mt-4 lg:mt-6">
            {renderContent()}
          </div>
        </div>

        {/* Mobile Navigation (Bottom Fixed) */}
        <MobileNavbar currentPage={currentPage} setPage={setCurrentPage} />

      </div>
    </main>
  );
};

export default App;

