import { useState, useEffect } from 'react';

/**
 * Hook para efeito de "Scramble" (Decodificação) de texto
 * @param {string[]} texts - Array de textos para alternar
 * @param {number} duration - Duração do efeito de scramble
 * @param {number} pauseTime - Tempo de pausa entre palavras
 * @returns {string} - Texto atual com efeito
 */
export const useScramble = (texts, duration = 1000, pauseTime = 3000) => {
  const [displayText, setDisplayText] = useState(texts[0]);
  const [index, setIndex] = useState(0);

  const chars = '!<>-_\\/[]{}—=+*^?#________';

  useEffect(() => {
    let frame = 0;
    let queue = [];
    let timer = null;
    let scrambleTimer = null;

    const nextText = texts[index % texts.length];
    const currentText = displayText;
    const length = Math.max(currentText.length, nextText.length);

    // Configura a fila de caracteres para resolver
    for (let i = 0; i < length; i++) {
      const from = currentText[i] || '';
      const to = nextText[i] || '';
      const start = Math.floor(Math.random() * 40);
      const end = start + Math.floor(Math.random() * 40);
      queue.push({ from, to, start, end });
    }

    const update = () => {
      let output = '';
      let complete = 0;

      for (let i = 0; i < length; i++) {
        let { from, to, start, end, char } = queue[i];
        if (frame >= end) {
          complete++;
          output += to;
        } else if (frame >= start) {
          if (!char || Math.random() < 0.28) {
            char = chars[Math.floor(Math.random() * chars.length)];
            queue[i].char = char;
          }
          output += `<span style="opacity: 0.5">${char}</span>`;
        } else {
          output += from;
        }
      }

      // Limpar tags HTML para o estado (simplificado para este exemplo React)
      // Nota: Em uma implementação real, usaríamos dangerouslySetInnerHTML ou arrays de chars
      // Aqui vamos simplificar retornando apenas o texto limpo ou sujo
      const rawOutput = output.replace(/<[^>]*>/g, '');
      setDisplayText(rawOutput);

      if (complete === queue.length) {
        clearInterval(scrambleTimer);
        timer = setTimeout(() => {
          setIndex((prev) => prev + 1);
        }, pauseTime);
      } else {
        frame++;
      }
    };

    scrambleTimer = setInterval(update, duration / 30);

    return () => {
      clearInterval(scrambleTimer);
      clearTimeout(timer);
    };
  }, [index, texts, duration, pauseTime]);

  return displayText;
};

