import { useState, useEffect } from 'react';

export const useTypewriter = (texts, speed = 150) => {
  const [displayText, setDisplayText] = useState('');
  const [isDeleting, setIsDeleting] = useState(false);
  const [loopNum, setLoopNum] = useState(0);
  const [typingSpeed, setTypingSpeed] = useState(speed);

  useEffect(() => {
    const handleType = () => {
      const i = loopNum % texts.length;
      const fullText = texts[i];

      setDisplayText(isDeleting 
        ? fullText.substring(0, displayText.length - 1) 
        : fullText.substring(0, displayText.length + 1)
      );

      setTypingSpeed(isDeleting ? 50 : 100);

      if (!isDeleting && displayText === fullText) {
        setTimeout(() => setIsDeleting(true), 2000); 
      } else if (isDeleting && displayText === '') {
        setIsDeleting(false);
        setLoopNum(loopNum + 1);
      }
    };

    const timer = setTimeout(handleType, typingSpeed);
    return () => clearTimeout(timer);
  }, [displayText, isDeleting, loopNum, texts, typingSpeed]);

  return displayText;
};

import { useState } from 'react';

export const useModal = () => {
  const [selectedItem, setSelectedItem] = useState(null);

  const openModal = (item) => {
    setSelectedItem(item);
  };

  const closeModal = () => {
    setSelectedItem(null);
  };

  return {
    isOpen: !!selectedItem,
    selectedItem,
    openModal,
    closeModal
  };
};

export const stopPropagation = (e) => {
  if (e && e.stopPropagation) {
    e.stopPropagation();
  }
};

import { useState, useEffect } from 'react';

export const useScramble = (texts, speed = 60, pauseTime = 2000) => {
  const [displayText, setDisplayText] = useState(texts[0]);
  const [index, setIndex] = useState(0);

  useEffect(() => {
    let currentText = texts[index % texts.length];
    let iteration = 0;
    let timer = null;
    let interval = null;

    const chars = '!<>-_\\/[]{}—=+*^?#________';

    interval = setInterval(() => {
      const result = currentText
        .split("")
        .map((letter, i) => {
          if (i < iteration) {
            return currentText[i];
          }
          return chars[Math.floor(Math.random() * chars.length)];
        })
        .join("");

      setDisplayText(result);

      iteration += 1; 

      if (iteration > currentText.length) {
        clearInterval(interval);
        setDisplayText(currentText); 

        timer = setTimeout(() => {
          setIndex(prev => prev + 1);
        }, pauseTime);
      }
    }, speed);

    return () => {
      clearInterval(interval);
      if (timer) clearTimeout(timer);
    };
  }, [index, texts, speed, pauseTime]);

  return displayText;
};

